#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-2.0-only
# Copyright (C) 2026 htjulia <htjulia1@gmail.com>
#
# detect-dsm-releases.sh — look for DSM releases on Synology's GPL archive that ship an
# avoton kernel and a matching toolchain but have no versions/<ver>.env yet, and write one
# for each. Prints the new version names, one per line (nothing if there are none).
#
# A generated file is a starting point, not a verified release:
#   - EXPECT_VERMAGIC is derived from the toolchain's kernel version ("<kver> SMP mod_unload")
#   - EXPECT_MODSIZE / EXPECT_IMPORTS are copied from the newest existing release of the same
#     kernel series (left empty for a new series — the build then fails until filled in)
#   - the archive hashes are left empty; build.sh prints them (out/<ver>/inputs.env)
# Only releases newer than the newest file in versions/ are considered.
set -euo pipefail

cd "$(dirname "$0")/.."
# Every regex match on stdin, one per line (portable stand-in for grep -oE).
matches() { awk -v re="$1" '{ while (match($0, re)) { print substr($0, RSTART, RLENGTH); $0 = substr($0, RSTART + RLENGTH) } }'; }
ARCHIVE=https://archive.synology.com/download/ToolChain
PLATFORM=${PLATFORM:-avoton}
PLATFORM_LABEL=${PLATFORM_LABEL:-Avoton}

list_versions() { for f in versions/*.env; do f=${f#versions/}; echo "${f%.env}"; done | sort -V; }
newest=$(list_versions | tail -1)
page() { curl -fsSL --retry 3 "$1"; }

candidates=$(page "$ARCHIVE/Synology%20NAS%20GPL%20Source" \
	| matches 'href="/download/ToolChain/Synology%20NAS%20GPL%20Source/[0-9][^"/]*"' \
	| sed 's#.*/##; s#"$##' | sort -uV)

for ver in $candidates; do
	[ "$(printf '%s\n%s\n' "$newest" "$ver" | sort -V | tail -1)" = "$ver" ] && [ "$ver" != "$newest" ] || continue
	[ -f "versions/$ver.env" ] && continue

	kernel_url=$(page "$ARCHIVE/Synology%20NAS%20GPL%20Source/$ver" \
		| matches "href=\"https://[^\"]*/$ver/$PLATFORM/linux-[^\"]*\\.txz\"" | sed 's/^href="//; s/"$//' | head -1 || true)
	toolchain_url=$(page "$ARCHIVE/toolchain/$ver" 2>/dev/null \
		| matches "href=\"https://[^\"]*%28$PLATFORM_LABEL%29/[^\"]*x86_64[^\"]*\\.txz\"" | sed 's/^href="//; s/"$//' | head -1 || true)
	if [ -z "$kernel_url" ] || [ -z "$toolchain_url" ]; then
		echo "skip $ver: no $PLATFORM kernel or toolchain in the archive" >&2
		continue
	fi

	kernel_dir=$(basename "$kernel_url" .txz)                                    # linux-3.10.x
	kver=$(printf '%s' "$toolchain_url" | sed -n 's/.*Linux%20\([0-9.]*\)%20.*/\1/p')   # 3.10.108
	series=$(printf '%s' "$kver" | cut -d. -f1-2)                                # 3.10
	prefix=$(basename "$toolchain_url" | sed -n 's/.*_\(x86_64\)-GPL\.txz/\1-pc-linux-gnu/p')

	# Carry the measured values over from the newest release of the same series.
	modsize='' imports=''
	for v in $(list_versions | sort -V -r); do
		f=versions/$v.env
		if [ "$(sed -n 's/^KERNEL_SERIES=//p' "$f")" = "$series" ]; then
			modsize=$(sed -n 's/^EXPECT_MODSIZE=//p' "$f")
			imports=$(sed -n 's/^EXPECT_IMPORTS=//p' "$f")
			break
		fi
	done

	cat > "versions/$ver.env" <<EOF
# SPDX-License-Identifier: GPL-2.0-only
# DSM $ver ($PLATFORM). Generated by scripts/detect-dsm-releases.sh — NOT verified on hardware.
# Before setting VERIFIED_*: confirm EXPECT_VERMAGIC and EXPECT_MODSIZE on a NAS running
# this release (README.md, "Adding a DSM release").

PLATFORM=$PLATFORM

KERNEL_URL="$kernel_url"
KERNEL_SHA256=
KERNEL_DIR_NAME=$kernel_dir
TOOLCHAIN_URL="$toolchain_url"
TOOLCHAIN_SHA256=
TOOLCHAIN_PREFIX=$prefix

KERNEL_SERIES=$series

EXPECT_VERMAGIC="$kver SMP mod_unload"
EXPECT_MODSIZE=$modsize
EXPECT_IMPORTS=$imports

VERIFIED_SHA256=
VERIFIED_ON=
VERIFIED_NOTE=
EOF
	echo "$ver"
done
